const rawBody = $input.first().json.body || $input.first().json;
const question = (rawBody.question || '').trim();
const systemPrompt = (rawBody.systemPrompt || '').trim();
const cardA = rawBody.interaction?.cardA || null;
const cardB = rawBody.interaction?.cardB || null;

/* Normalize text removing accents for guardrail checks */
const cleanText = question.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const nonMtgKeywords = ['nau an', 'thoi tiet', 'bong da', 'lap trinh', 'crypto', 'bitcoin', 'thoi tiet ha noi'];
const isOutOfScope = nonMtgKeywords.some(kw => cleanText.includes(kw));

let intent = 'RULES_DISPUTE';
let searchQuery = '';

if (isOutOfScope) {
  intent = 'OUT_OF_SCOPE';
} else if (!cardA && !cardB && /^(tim|tra cuu|search|show me|find)/i.test(question)) {
  intent = 'CARD_SEARCH';
  searchQuery = question.replace(/^(tim|tra cuu|search|show me|find)\s*(la bai|card)?/i, '').trim();
}

return [{
  json: {
    id: rawBody.requestId || 'req_' + Date.now(),
    question,
    systemPrompt,
    context: rawBody.context,
    searchQuery,
    cardA,
    cardB,
    intent
  }
}];

const inputData = $input.first().json;
const cards = (inputData.data || []).slice(0, 5).map(c => ({
  name: c.name,
  manaCost: c.mana_cost || '',
  typeLine: c.type_line || '',
  oracleText: c.oracle_text || '',
  imageUri: c.image_uris?.normal || c.card_faces?.[0]?.image_uris?.normal || ''
}));

const query = $('Intent Classifier & Guardrail').first().json.question;
const reqId = $('Intent Classifier & Guardrail').first().json.id;

return [{
  json: {
    id: reqId,
    query: query,
    verdict: cards.length > 0 ? 'YES' : 'NO',
    verdictTitle: cards.length > 0 ? `Tìm thấy ${cards.length} thẻ bài MTG phù hợp` : 'Không tìm thấy thẻ bài phù hợp',
    summary: cards.length > 0 ? `Các lá bài phù hợp nhất với mô tả: ${cards.map(c => c.name).join(', ')}.` : `Không tìm thấy thẻ bài nào khớp với từ khóa "${query}".`,
    stackSteps: [],
    crRules: [],
    cardNames: cards.map(c => c.name),
    isCached: false
  }
}];

