const responseBody = $input.first().json;
const reqInfo = $('Intent Classifier & Guardrail').first().json;

const choice = responseBody.choices?.[0];
if (choice?.finish_reason !== 'stop' || !choice.message?.content?.trim()) throw new Error('Incomplete DeepSeek response');
const parsed = JSON.parse(choice.message.content);
if (!['YES', 'NO', 'CONDITIONAL'].includes(parsed.verdict) ||
    ![parsed.summary, parsed.verdictTitle].every(v => typeof v === 'string' && v.trim()) ||
    ![parsed.crRules, parsed.stackSteps].every(a => Array.isArray(a) && a.every(v => typeof v === 'string'))) {
  throw new Error('Invalid DeepSeek verdict');
}

return [{
  json: {
    id: reqInfo.id,
    query: reqInfo.question,
    verdict: parsed.verdict || 'CONDITIONAL',
    verdictTitle: parsed.verdictTitle || 'Phán quyết trọng tài MTG',
    summary: parsed.summary || 'Đã phân tích tương tác theo luật MTG.',
    stackSteps: parsed.stackSteps || [],
    crRules: parsed.crRules || [],
    cardNames: parsed.cardNames || parsed.relatedCards || [],
    isCached: false
  }
}];
